def register_point_module(apps, schema_editor):
    """Register the module globally; no Organization or plan is granted it."""
    db = schema_editor.connection.alias
    Catalog = apps.get_model('platform_core', 'ERPCatalog')
    Module = apps.get_model('platform_core', 'ERPProductModule')
    Resource = apps.get_model('platform_core', 'ERPProductResource')
    product = Catalog.objects.using(db).get(code='gestao-publica')
    module, _ = Module.objects.using(db).get_or_create(
        erp_id=product.pk,
        code='ponto_digital',
        defaults={'name': 'Ponto Digital Municipal', 'active': True, 'sort_order': 45},
    )
    resources = (
        ('marcacoes', 'Registros web e móvel com autoria e auditoria'),
        ('jornadas_escalas', 'Jornadas, horários, escalas e vigências'),
        ('aprovacoes', 'Justificativas e solicitações de horas extras'),
        ('espelho_periodo', 'Espelho mensal e fechamento versionado'),
        ('banco_horas', 'Movimentações de saldo com origem auditada'),
        ('pwa', 'PWA independente sem cache de páginas autenticadas'),
    )
    for order, (code, name) in enumerate(resources, start=1):
        Resource.objects.using(db).get_or_create(
            module_id=module.pk,
            code=code,
            defaults={'name': name, 'active': True, 'sort_order': order},
        )


